content.solution_code:
class Spacecraft {
  constructor(name) {
    this.name = name;
  }

  launch() {
    return `${this.name} is launching!`;
  }
}

class CargoShip extends Spacecraft {
  constructor(name, cargoCapacity) {
    super(name);
    this.cargoCapacity = cargoCapacity;
    this.currentCargo = 0;
  }

  loadCargo(amount) {
    if (this.currentCargo + amount <= this.cargoCapacity) {
      this.currentCargo += amount;
      return `${this.name} loaded ${amount} tons. Current cargo: ${this.currentCargo}/${this.cargoCapacity}`;
    } else {
      return `Cannot load ${amount} tons. Capacity exceeded! Current cargo: ${this.currentCargo}/${this.cargoCapacity}`;
    }
  }
}

